const body = $input.first().json.body ?? $input.first().json;
const text = (body.text ?? '').toString();
if (!text.trim()) throw new Error('empty_selection');
const target = body.target_language === 'en' ? 'en' : 'nl';
const voiceId = body.voice_template_id ?? null;
// crude source detection: count Dutch-specific function words
const lower = text.toLowerCase();
const nlMarkers = ['de ', 'het ', 'een ', 'is ', 'zijn ', 'niet ', 'maar ', 'voor ', 'wat ', 'dat '];
const hits = nlMarkers.filter((m) => lower.includes(m)).length;
const source = hits >= 2 ? 'nl' : 'en';
return [{ json: { text, target_language: target, source_language: source, voice_id: voiceId } }];

const voice = $input.first().json;
const ctx = $('parse').first().json;
const target = ctx.target_language === 'nl' ? 'Dutch (Nederlands)' : 'English';
const tone = voice?.tone || 'plainspoken, slightly skeptical of hype';
const style = voice?.writing_style || 'short opening sentence, concrete numbers, no filler adjectives';
const banned = Array.isArray(voice?.banned_words) ? voice.banned_words.join(', ') : '';
const system = `You translate prose to ${target} for a single author, preserving voice.

Voice tone: ${tone}
Writing style: ${style}${banned ? `
Banned words in target language (never use): ${banned}` : ''}

Rules:
- Output ONLY the translated text, no preface, no quotes, no JSON.
- Technical terms STAY in English (API, queue, latency, dashboard, etc.).
- Names, brand names, code keywords, acronyms stay as-is.
- Preserve sentence rhythm and length where possible.
- Match the source's register exactly: don't make it more formal or more casual.
- Never invent meaning the source didn't contain.`;
return [{ json: { ...ctx, system_prompt: system } }];

let text = $input.first().json.message ?? $input.first().json.text ?? $input.first().json.content ?? '';
text = text.trim();
text = text.replace(/^['\"\u201C]+|['\"\u201D]+$/g, '');
// Light heuristic for which English terms slipped through unchanged in NL output.
const ctx = $('parse').first().json;
let detected = [];
if (ctx.target_language === 'nl') {
  const candidates = ['API','SDK','queue','dashboard','latency','retry','endpoint','workflow','prompt','token','agent'];
  detected = candidates.filter((c) => new RegExp('\\b'+c+'\\b','i').test(text));
}
return [{ json: {
  text,
  source_language: ctx.source_language,
  detected_terms_kept_english: detected,
} }];
